export function pseudonymize(text: string) {
  return text.replace(authorPattern, name => lookup[name.toLowerCase().replace(/[.\s]/g, '')] ?? name);
}

export function pseudonymizeProfile<T>(value: T): T {
  if (typeof value === 'string') return pseudonymize(value) as T;
  if (Array.isArray(value)) return value.map(pseudonymizeProfile) as T;
  if (value && typeof value === 'object') return Object.fromEntries(Object.entries(value).map(
    ([key, entry]) => [pseudonymize(key), pseudonymizeProfile(entry)]
  )) as T;
  return value;
}
